<template><div><UsabilityView v-if="usabilityEnabled"/><Card v-else><h2>平台接收关系</h2><p>仅管理平台接收方关系，不提供资金执行操作。</p><StatusPanel :error="error" :pending="pending" :busy="busy" :loading="loading" @recover="recover" @retry="retryOriginal" @abandon="abandonPending"/><div class="s1-toolbar"><Input v-model="configId" placeholder="渠道配置编号（可选）" style="width:250px"/><Button @click="page=1;reload()">查询</Button><Button type="primary" :disabled="pending" @click="form={configId,displayName:'',reason:''};show=true">新增关系</Button></div><Table :columns="columns" :data="records" :loading="loading" no-data-text="暂无接收关系"><template slot="state" slot-scope="{row}">{{label(row.mode)}} / {{label(row.state)}} / {{row.enabled?'启用':'停用'}}</template><template slot="action" slot-scope="{row}"><Button size="small" @click="detail(row)">详情与核验</Button></template></Table><Page :total="total" :current="page" :page-size="size" show-total @on-change="page=$event;reload()"/><Drawer v-model="show" title="新建平台接收关系" width="760" :mask-closable="false"><FieldsForm v-model="form" :fields="fields" :disabled="busy||pending"/><Button type="primary" :loading="busy" :disabled="pending" @click="save">保存未核验关系</Button></Drawer><Drawer v-model="detailShow" title="接收关系与核验历史" width="85"><template v-if="selected"><div class="s1-toolbar"><Button :disabled="busy||pending" @click="command('sync')">同步核验关系</Button><Button :disabled="busy||pending" @click="command(selected.receiver.enabled?'disable':'enable')">{{selected.receiver.enabled?'停用':'启用'}}</Button></div><RecordDetail :value="selected"/></template></Drawer></Card></div></template>
<script>import {usabilityEntry} from './usability/enabled';import {leaveGuard} from './usability/entry';import UiView from './usability/Receivers';import {pageMixin} from './shared';import {s1Read} from '@/api/stage1';import StatusPanel from './StatusPanel';import FieldsForm from './FieldsForm';import RecordDetail from './RecordDetail';const LegacyView = {mixins:[pageMixin],components:{StatusPanel,FieldsForm,RecordDetail},data:()=>({configId:'',form:{},show:false,detailShow:false,fields:[{key:'configId',label:'渠道配置编号',required:true,max:19},{key:'displayName',label:'平台主体名称',required:true,max:120},{key:'mockAccount',label:'模拟接收方账号',max:64,help:'MOCK 配置填写 MOCK_ 开头账号；真实模式不填写。'},{key:'accountReference',label:'真实账号受控引用',max:64,help:'REAL 配置填写受控凭据引用；不在表单粘贴账户秘密。'},{key:'reason',label:'原因',type:'textarea',required:true,max:500}],columns:[{title:'平台主体',key:'displayName'},{title:'关系编号',key:'id',minWidth:180},{title:'配置编号',key:'configId',minWidth:180},{title:'状态',slot:'state',minWidth:210},{title:'操作',slot:'action',width:150}]}),mounted(){if(this.usabilityEnabled)return;const id=this.$route.query.configId;if(typeof id==='string'&&/^\d{1,19}$/.test(id))this.configId=id;this.reload();},methods:{reload(){return this.load('/receivers',{configId:this.configId||undefined});},async save(){const body={...this.form};if(!body.mockAccount)delete body.mockAccount;if(!body.accountReference)delete body.accountReference;try{await this.run('/receivers',body);this.show=false;await this.reload();}catch(_){}},async detail(row){try{this.selected=await s1Read('/receivers/'+row.id);this.detailShow=true;}catch(e){this.error=e.message;}},async command(action){const row=this.selected.receiver;const result=await this.reasonAction('/receivers/'+row.id+'/'+action,{sync:'同步核验平台接收关系',enable:'启用接收关系',disable:'停用接收关系'}[action],{expectedVersion:row.version});if(result){await this.detail(row);await this.reload();}}}};LegacyView.mixins.push(usabilityEntry);LegacyView.components={...LegacyView.components,UsabilityView:UiView};LegacyView.beforeRouteLeave=leaveGuard;LegacyView.beforeRouteUpdate=leaveGuard;export default LegacyView;</script><style scoped>.s1-toolbar{display:flex;gap:12px;margin:18px 0}.ivu-page{margin-top:18px}</style>
